        "name": "Jersey Perez Jr",
        "email": "joselito.perez.jr@accenture.com",
        "avatar_url": "https://secure.gravatar.com/avatar/265f89fa22412ee8591f76b84a5f1829?d=https%3A%2F%2Favatar-management--avatars.us-west-2.prod.public.atl-paas.net%2Finitials%2FJJ-5.png"
